-- Baseline generated by `prisma migrate diff`, then edited by hand to keep rules Prisma
-- cannot model: CHECK constraints and case-insensitive email uniqueness.

-- CreateTable
CREATE TABLE "users" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL COLLATE NOCASE,
    "role" TEXT NOT NULL CHECK ("role" IN ('owner', 'vet')),
    "password_hash" TEXT NOT NULL
);

-- CreateTable
CREATE TABLE "sessions" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "user_id" TEXT NOT NULL,
    "expires_at" BIGINT NOT NULL CHECK ("expires_at" > 0),
    CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id")
);

-- CreateTable
CREATE TABLE "pets" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "owner_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "species" TEXT NOT NULL CHECK ("species" IN ('Dog', 'Cat', 'Rabbit', 'Bird', 'Other')),
    "sex" TEXT NOT NULL CHECK ("sex" IN ('Male', 'Female')),
    "date_of_birth" TEXT,
    "approximate_age" TEXT,
    "breed" TEXT,
    "weight" REAL CHECK ("weight" > 0 AND "weight" <= 2000),
    "notes" TEXT,
    CONSTRAINT "pets_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users" ("id"),
    CHECK ("date_of_birth" IS NOT NULL OR "approximate_age" IS NOT NULL)
);

-- CreateTable
CREATE TABLE "cases" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "pet_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    CONSTRAINT "cases_pet_id_fkey" FOREIGN KEY ("pet_id") REFERENCES "pets" ("id")
);

-- CreateTable
CREATE TABLE "appointments" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "pet_id" TEXT NOT NULL,
    "owner_id" TEXT NOT NULL,
    "vet_id" TEXT,
    "scheduled_at" TEXT,
    "symptoms" TEXT NOT NULL,
    "status" TEXT NOT NULL CHECK ("status" IN ('AwaitingConfirmation', 'Confirmed', 'NeedsTime', 'Done', 'Cancelled')),
    "case_id" TEXT,
    "checkpoint_order" INTEGER CHECK ("checkpoint_order" > 0),
    "pet_needed" BOOLEAN CHECK ("pet_needed" IN (0, 1)),
    "created_at" TEXT NOT NULL,
    "completed_at" TEXT,
    "revision" INTEGER NOT NULL CHECK ("revision" >= 0),
    "actual_actives_recorded" BOOLEAN NOT NULL DEFAULT false CHECK ("actual_actives_recorded" IN (0, 1)),
    CONSTRAINT "appointments_owner_id_fkey" FOREIGN KEY ("owner_id") REFERENCES "users" ("id"),
    CONSTRAINT "appointments_vet_id_fkey" FOREIGN KEY ("vet_id") REFERENCES "users" ("id"),
    CONSTRAINT "appointments_pet_id_owner_id_fkey" FOREIGN KEY ("pet_id", "owner_id") REFERENCES "pets" ("id", "owner_id"),
    CONSTRAINT "appointments_case_id_pet_id_fkey" FOREIGN KEY ("case_id", "pet_id") REFERENCES "cases" ("id", "pet_id"),
    CHECK (
      ("case_id" IS NULL AND "checkpoint_order" IS NULL AND "pet_needed" IS NULL)
      OR ("case_id" IS NOT NULL AND "checkpoint_order" IS NOT NULL AND "pet_needed" IS NOT NULL)
    )
);

-- CreateTable
CREATE TABLE "products" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "name" TEXT NOT NULL,
    "unit" TEXT NOT NULL,
    "stock" REAL NOT NULL CHECK ("stock" >= 0)
);

-- CreateTable
CREATE TABLE "movements" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "product_id" TEXT NOT NULL,
    "type" TEXT NOT NULL CHECK ("type" IN ('Received', 'Correction', 'Used')),
    "quantity" REAL NOT NULL CHECK ("quantity" != 0),
    "reason" TEXT,
    "performed_by" TEXT NOT NULL,
    "performed_at" TEXT NOT NULL,
    "appointment_id" TEXT,
    CONSTRAINT "movements_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products" ("id"),
    CONSTRAINT "movements_performed_by_fkey" FOREIGN KEY ("performed_by") REFERENCES "users" ("id"),
    CONSTRAINT "movements_appointment_id_fkey" FOREIGN KEY ("appointment_id") REFERENCES "appointments" ("id"),
    CHECK ("type" != 'Received' OR "quantity" > 0),
    CHECK ("type" != 'Used' OR ("quantity" < 0 AND "appointment_id" IS NOT NULL)),
    CHECK ("type" != 'Correction' OR ("reason" IS NOT NULL AND length(trim("reason")) > 0))
);

